class Solution {
public:
    int countGoodRectangles(vector<vector<int>>& rectangles) {
        vector<int> sides;
        sides.reserve(rectangles.size());
        for (auto& r : rectangles)
            sides.push_back(min(r[0], r[1]));
        int best = *max_element(sides.begin(), sides.end());
        return (int)count(sides.begin(), sides.end(), best);
    }
};

