class Solution {
    public int countGoodRectangles(int[][] rectangles) {
        int[] sides = new int[rectangles.length];
        int idx = 0;
        for (int[] r : rectangles)
            sides[idx++] = Math.min(r[0], r[1]);
        int best = Integer.MIN_VALUE;
        for (int s : sides)
            best = Math.max(best, s);
        int count = 0;
        for (int s : sides)
            if (s == best) count++;
        return count;
    }
};

