class Solution:
    def countGoodRectangles(self, rectangles: List[List[int]]) -> int:
        best = count = 0
        for l, w in rectangles:
            side = l if l < w else w
            if side > best:
                best, count = side, 1
            elif side == best:
                count += 1
        return count

