class Solution {
public:
    int countGoodRectangles(vector<vector<int>>& rectangles) {
        int best = 0, count = 0;
        for (auto& r : rectangles) {
            int side = min(r[0], r[1]);
            if (side > best) { best = side; count = 1; }
            else if (side == best) count++;
        }
        return count;
    }
};

